"""spike11a: assemble results/spike11a/table.md from the raw json files (no new simulation)."""
import json, os, numpy as np
R = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'results', 'spike11a'); L = lambda n: json.load(open(os.path.join(R, n))) if os.path.exists(os.path.join(R, n)) else {}
def ci(x, n=20000, seed=0):
    x = np.asarray(x, float); r = np.random.default_rng(seed); b = x[r.integers(0, len(x), (n, len(x)))].mean(1); return np.quantile(b, .025), np.quantile(b, .975)
def pct(v): return f'{100 * v:.1f}'
def row(name, s): s = np.asarray(s, float); lo, hi = ci(s); return f'| {name} | {len(s)} | {pct(s.mean())} [{pct(lo)}, {pct(hi)}] |'
def diff(a, b, seed=1):
    d = np.asarray(a, float) - np.asarray(b, float); lo, hi = ci(d, seed=seed); return f'{100 * d.mean():+.1f} pp [{100 * lo:+.1f}, {100 * hi:+.1f}]'
out = ['# spike11a tables (generated by experiments/spike11a/report11.py)', '']
t1 = L('step1_teacher.json'); out += ['## 1. Teacher query cost and quality (CAL 1000-1049, abc x1, n=50)', '', '| teacher | success % | queries | cost per query s (mean / p90) | plan time per episode s |', '|---|---|---|---|---|']
for k, v in t1.items(): out.append(f"| {k} | {pct(v['succ'])} [{pct(v['ci'][0])}, {pct(v['ci'][1])}] | {v['n_queries']} | {v['q_cost_mean']:.2f} / {v['q_cost_p90']:.2f} | {v['per_episode_plan_s']:.1f} |")
ct = L('canon_teacher.json').get('canon_teacher'); mm, mc, gr = L('multimodal.json'), L('multimodal_canon.json'), L('canon_grid.json')
if ct: out += ['', f"Canonical (continuation) teacher: success CAL1 {pct(ct['cal'])}, CAL2 {pct(ct['cal2'])}, all {pct(ct['all'])} [{pct(ct['ci'][0])}, {pct(ct['ci'][1])}]; plan time {ct['plan_s']:.1f} s/episode."]
if mm: out += ['', f"Plan multimodality (12 CAL scenarios x 4 independent CMA-ES streams, RMS of arm reference differences): standard teacher within-scenario {mm['rms_within_scenario_rad']:.2f} rad vs between-scenario {mm['rms_between_scenarios_rad']:.2f} rad; canonical teacher within {mc.get('rms_within_scenario_rad', float('nan')):.2f} vs between {mc.get('rms_between_scenarios_rad', float('nan')):.2f} rad."]
b = L('base.json'); out += ['', '## 2. Baselines on CAL (abc x1, SUBF=4)', '', '| method | set | n | success % [95% CI] |', '|---|---|---|---|']
for k, lab in (('oracle', 'T-oracle (spike11a teacher, standard planner)'), ('adapt3full', 'T-adapt3-full'), ('nom', 'T-nom')):
    for s, nm in (('cal', 'CAL1 1000-1049'), ('cal2', 'CAL2 1050-1099')):
        if f'{k}_{s}' in b: out.append(f"| {lab} | {nm} | 50 | {pct(b[f'{k}_{s}']['succ'])} [{pct(b[f'{k}_{s}']['ci'][0])}, {pct(b[f'{k}_{s}']['ci'][1])}] |")
    if f'{k}_cal' in b: s_ = b[f'{k}_cal']['per_seed'] + b[f'{k}_cal2']['per_seed']; out.append(row(f'{lab}', s_).replace('| ' + lab + ' |', f'| {lab} | CAL1+CAL2 |'))
AD = np.array(b['adapt3full_cal']['per_seed'] + b['adapt3full_cal2']['per_seed']) if b else None
out += ['', '## 3. Students on CAL1 (selection set, n=50) / CAL2 (fresh, n=50)', '', '| student | episodes (teacher-labelled) | CAL1 % | CAL2 % | CAL1+CAL2 % | train-seed rollout success % |', '|---|---|---|---|---|---|']
bc, dart, dg = L('bc.json'), L('dart.json'), L('dagger.json'); cd, f1, f2, c2 = L('canon_dagger.json'), L('final1.json'), L('final.json'), L('canon_dagger2.json')
for k, v in bc.items():
    if k.startswith('bc_'): out.append(f"| BC window {k[3:]} (standard teacher) | {v['episodes']} | {pct(v['succ'])} | - | - | - |")
for k, v in dart.items(): out.append(f"| DART sigma 5 Nm rho 0.9 (standard teacher; BC data + 400 noisy) | {v['episodes']} | {pct(v['succ'])} | - | - | - |")
for n, dd in dg.items():
    for k, v in dd.items():
        if 'succ' in v and v['succ'] is not None: out.append(f"| {n} {k} | {v['episodes']} | {pct(v['succ'])} | - | - | {pct(v['student_train_succ']) if v.get('student_train_succ') is not None else '-'} |")
for n, dd in cd.items():
    for k, v in dd.items():
        if 'succ' in v: 
            nm = f'{n} {k}'; c2v = f2.get(f'{n}_{k.replace("iter", "it")}'); out.append(f"| {nm} | {v['episodes']} | {pct(v['succ'])} | {pct(c2v['succ']) if c2v else '-'} | {pct((v['succ'] + c2v['succ']) / 2) if c2v else '-'} | {pct(v['student_train_succ']) if v.get('student_train_succ') is not None else '-'} |")
for n, dd in c2.items():
    for k, v in dd.items(): out.append(f"| {n} {k} | {v['episodes']} | {pct(v['cal1'])} | {pct(v['cal2'])} | {pct((v['cal1'] + v['cal2']) / 2)} | {pct(v['train_succ'])} |")
fl = L('flow.json')
for k, v in fl.items(): out.append(f"| arena Flow (1 Euler step, {k.split('_')[-1]}), offline on canon_dagger3 aggregated data ({v['samples']} samples) | 1600 | {pct(v['cal1'])} | {pct(v['cal2'])} | {pct(v['both'])} | - |")
fr = L('fresh.json')
if fr:
    out += ['', '## 4. Fresh unseen seeds 700000+ (never used for training or selection), seed-derived plant, abc x1', '', '| method | n | success % [95% CI] | paired diff vs T-adapt3-full |', '|---|---|---|---|']
    A3 = fr['adapt3full']['per_seed']
    for k, v in fr.items():
        if k == 'oracle' or not isinstance(v, dict): continue
        out.append(row(k, v['per_seed']) + ' ' + (diff(v['per_seed'], A3) if k != 'adapt3full' else '-') + ' |')
open(os.path.join(R, 'table.md'), 'w').write('\n'.join(out) + '\n'); print('\n'.join(out))
